mapper.select:
bm_storage_material_batch.is_deleted = 0 and bm_material.is_deleted = 0 and bm_material_category.is_deleted = 0
and bm_material_category.category_type = #{pageQuery.categoryType}
and bm_storage_material_batch.material_id = #{pageQuery.materialId}
and bm_storage_material_batch.material_batch_no like concat('%',#{pageQuery.materialBatchNo},'%')
order by bm_material.merge_code asc, bm_storage_material_batch.material_batch_no

select batch.id as materialBatchId, batch.material_id, batch.material_batch_no, batch.original_batch_no as originalCode, batch.expired_date, batch.factory_batch_no as originalBatchNo, batch.hydration, batch.no_hydration_content, batch.supplier, batch.producer, batch.produce_date, batch.report_no, batch.licence_no, material.unit_id, sum(material.reserve_quantity + material.available_quantity) as materialQuantity from bm_storage_material_batch batch join bm_storage_material material on material.storage_material_batch_id = batch.id join bm_storage_material_reserve reserve on reserve.storage_material_id = material.id where material.is_deleted = 0 and reserve.is_deleted = 0 and reserve.batch_id = #{productPlanId} and batch.id in
#{materialBatchId}
group by batch.id order by batch.material_batch_no
